"use strict";var Router={currentRoute:window.location.hash.slice(1)||"/",navigate:function navigate(route){Router.currentRoute=route;window.location.hash=route;window.dispatchEvent(new Event("routechange"))},back:function back(){window.history.back()},init:function init(){window.addEventListener("hashchange",function(){Router.currentRoute=window.location.hash.slice(1)||"/";window.dispatchEvent(new Event("routechange"))});Router.currentRoute=window.location.hash.slice(1)||"/"}};